CREATE TABLE loan_financial_statements (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES loan_applications(id) ON DELETE CASCADE, uploaded_by UUID NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK (kind IN ('mobile_money','bank')), period_months INTEGER NOT NULL CHECK (period_months IN (3,6,12)), filename TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, uploaded_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(application_id,kind));
